import 'package:flutter/material.dart';
import '../models/recipe.dart';
import '../services/temperament_service.dart';
import '../widgets/shared.dart';
class RecipeDetailScreen extends StatelessWidget {final Recipe recipe;final bool favorite;final ValueChanged<bool>? onFavorite;const RecipeDetailScreen({super.key,required this.recipe,this.favorite=false,this.onFavorite});@override Widget build(BuildContext c){final t=TemperamentService.analyze(recipe.ingredients);return Directionality(textDirection:TextDirection.rtl,child:Scaffold(appBar:AppBar(title:Text(recipe.name),actions:[IconButton(onPressed:()=>onFavorite?.call(!favorite),icon:Icon(favorite?Icons.favorite:Icons.favorite_border))]),body:ListView(padding:const EdgeInsets.all(16),children:[Container(height:170,decoration:BoxDecoration(color:Color(recipe.imageColor),borderRadius:BorderRadius.circular(24)),child:Center(child:Text(recipe.emoji,style:const TextStyle(fontSize:76)))),SectionTitle(recipe.name),Text('⏱ ${recipe.minutes} دقیقه  •  ${recipe.difficulty}  •  ${recipe.cityTags.join('، ')}'),SectionTitle('مواد لازم'),for(final i in recipe.ingredients)ListTile(leading:CircleAvatar(backgroundColor:i.temperament=='گرم'?Colors.orange.shade200:i.temperament=='سرد'?Colors.lightBlue.shade100:Colors.green.shade100,radius:7),title:Text(i.name),trailing:Text(i.quantity)),Card(color:const Color(0xFFE5EDDF),child:ListTile(leading:const Icon(Icons.spa),title:Text('طبع کلی: ${t.label}'),subtitle:Text('امتیاز تعادل: ${t.score} • متناسب با ذائقه متعادل سرو شود.'))),SectionTitle('روش پخت'),for(var i=0;i<recipe.steps.length;i++)ListTile(leading:CircleAvatar(child:Text('${i+1}')),title:Text(recipe.steps[i])),SectionTitle('نکته‌ها'),for(final b in recipe.benefits)Text('• $b',style:const TextStyle(height:2))])));}}
